-- Haul-out sites and the pinniped reports that fall within them (decision 040,
-- bd salish-4pr.1, GH #385).
--
-- A haul-out site is a row we hold, not a cluster we compute: a name, a point,
-- a radius, and what the WDFW atlas (Jeffries et al. 2000) recorded there. A
-- pinniped report belongs to a site when it falls within the site's radius —
-- a spatial join that claims the report was made near a known site and nothing
-- about which animals or how many (decision 027).
--
-- The seed is the atlas's Salish Sea regions (6–14: the Strait of Juan de Fuca,
-- Hood Canal, the eastern bays, Puget Sound, the San Juans, and the Canadian
-- side to Race Rocks), 362 rows for 270 site codes — a site the atlas maps at more
-- than one point is one row per point, sharing atlas_code. The rows come from
-- docs/reference/jeffries-2000-haulout-sites.csv, a machine extraction of the
-- PDF's tables that nobody has yet proofed, so verified is false on every row
-- (salish-4pr.3). Coordinates are the atlas's NAD27, up to ~200 m off WGS84;
-- no site is precise enough for that to matter against a 500 m radius.
--
-- location is a lon_lat composite rather than a geography so PostgREST hands
-- the client {lon, lat} the way public.occurrences already does; the view
-- builds the geography it needs. At a few hundred sites nothing wants an index.
CREATE TABLE public.haulouts (
  id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name text NOT NULL,
  location public.lon_lat NOT NULL,
  -- How far from the point a report still counts. 500 m covers an observer on
  -- shore looking at a float or rock, plus the atlas's datum offset.
  radius_m integer NOT NULL DEFAULT 500 CHECK (radius_m BETWEEN 50 AND 5000),
  -- The atlas's regional grouping, e.g. 'Puget Sound (Whidbey Island to Olympia)'.
  region text,
  -- The atlas's fields, verbatim. A seeded row's id IS the CSV's first column
  -- (the atlas's running row number), so /haulouts/340 is atlas row 340 and a
  -- proofreader can find it; hand-added sites number from 1001.
  atlas_code text,
  atlas_species text[],    -- PV harbor seal, ZC California sea lion, EJ Steller sea lion, MA elephant seal
  atlas_count text,        -- peak group size class: <10, <100, 100-500, 500>
  atlas_tidal_use text,    -- LOW, HIGH, ALL
  atlas_description text,
  -- Our own curated prose, Markdown: the story, viewing access, survey reports.
  story text,
  -- Whether a person has checked this row against the atlas PDF.
  verified boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE public.haulouts IS 'Pinniped haul-out sites: our own list, seeded from Jeffries et al. 2000 (decision 040).';

ALTER TABLE public.haulouts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Haul-out sites are publicly readable"
  ON public.haulouts FOR SELECT USING (true);


SELECT setval(pg_get_serial_sequence('public.haulouts', 'id'), 1000);

-- One row per (site, pinniped report within the site's radius). Pinnipeds are
-- everything under the families Phocidae and Otariidae in the iNaturalist
-- taxonomy mirror, walked by parent_id so a subspecies or a family-rank report
-- both qualify; the two families are named rather than the misnomered
-- superfamily Phocoidea (decision 027). The report's stated accuracy rides
-- along so the page can label one whose accuracy exceeds the radius as only
-- approximately located; the radius itself is strict, because widening it by
-- accuracy would attach a 5 km report to every site along a shoreline.
CREATE VIEW public.haulout_occurrences AS
WITH RECURSIVE pinniped AS (
  SELECT id, scientific_name FROM inaturalist.taxa
   WHERE rank = 'family' AND scientific_name IN ('Phocidae', 'Otariidae')
  UNION
  SELECT t.id, t.scientific_name FROM inaturalist.taxa t JOIN pinniped p ON t.parent_id = p.id
)
SELECT
  h.id AS haulout_id,
  o.id AS occurrence_id,
  o.observed_at,
  o.location,
  o.accuracy,
  round(gis.st_distance(site.geog, report.geog))::integer AS distance_m,
  o.taxon,
  o.photos,
  o.url,
  o.attribution,
  o.observer,
  o.body
FROM public.haulouts h
CROSS JOIN LATERAL (
  SELECT gis.st_setsrid(gis.st_makepoint((h.location).lon, (h.location).lat), 4326)::gis.geography AS geog
) site
JOIN public.occurrences o
  ON (o.taxon).scientific_name IN (SELECT scientific_name FROM pinniped)
 AND (o.location).lon IS NOT NULL
CROSS JOIN LATERAL (
  SELECT gis.st_setsrid(gis.st_makepoint((o.location).lon, (o.location).lat), 4326)::gis.geography AS geog
) report
WHERE gis.st_dwithin(site.geog, report.geog, h.radius_m);

-- The grants ship with the relations (README convention); the pinned set in
-- supabase/read-grants.test.ts grows by these two.
REVOKE ALL ON public.haulouts FROM anon, authenticated;
REVOKE ALL ON public.haulout_occurrences FROM anon, authenticated;
GRANT SELECT ON public.haulouts TO anon, authenticated;
GRANT SELECT ON public.haulout_occurrences TO anon, authenticated;
